-- P1-10 Studio hardening and Simple mode. Generated by drizzle-kit from
-- db/schema.ts, then hand-adjusted to IF NOT EXISTS (as 0000 and 0001 were):
-- the API's table bootstrap (worker/api/router.ts ensureStudioTables) creates
-- these tables idempotently, so a worker that served requests before this
-- migration ran must not make it fail. CREATE statements only: the Studio
-- migration gate (scripts/check-migrations-additive.mjs) refuses anything else.
--
--   studio_user_prefs   the Simple/Advanced editor mode per account (owner
--                       decisions S6/S7; no row = Simple). No CHECK on mode,
--                       so a future mode needs no table rebuild.
--   studio_rate_limits  the D1 fixed-window rate limit (the main site's pattern).
CREATE TABLE IF NOT EXISTS `studio_rate_limits` (
	`key` text PRIMARY KEY NOT NULL,
	`window_start` integer NOT NULL,
	`count` integer DEFAULT 0 NOT NULL
);
--> statement-breakpoint
